// Title: Add a custom CSS class to the header row of HTML generated by Aspose.Cells using C#
// Common Searches: C# add class attribute to first <tr> in HTML produced by Aspose.Cells | how to inject inline CSS for header rows when exporting Excel to HTML with Aspose.Cells | Aspose.Cells HTML export modify header row style programmatically in .NET | using regex to set class="header-row" on the header table row in Aspose.Cells output | save Excel workbook as single‑file HTML and customize header styling with C#
// Tags: Aspose.Cells HTML export custom header CSS | C# inject inline style into generated HTML | regex add class to first table row .NET | modify Aspose.Cells HTML output header row | single‑file HTML export with base64 images Aspose.Cells | custom CSS class for Excel header in HTML

using System;
using System.IO;
using System.Text;
using System.Text.RegularExpressions;
using Aspose.Cells;

namespace AsposeCellsHtmlHeaderClassDemo
{
    // The example creates a workbook, fills it with sample data, applies a bold gray style to the header row, and saves the sheet as a single‑file HTML document using HtmlSaveOptions. It then reads the HTML, inserts a <style> block that defines a .header‑row class before the closing </head> tag, and uses a regular‑expression replace to add class="header‑row" to the first <tr> element (the header row). The modified HTML is written back, resulting in a styled header row without external resources.
    class Program
    {
        static void Main(string[] args)
        {
            try
            {
                // 1. Create a workbook and populate it with sample data
                Workbook workbook = new Workbook();
                Worksheet sheet = workbook.Worksheets[0];
                Cells cells = sheet.Cells;

                // Header row
                cells["A1"].PutValue("Product");
                cells["B1"].PutValue("Category");
                cells["C1"].PutValue("Price");

                // Data rows
                cells["A2"].PutValue("Laptop");
                cells["B2"].PutValue("Electronics");
                cells["C2"].PutValue(1200);

                cells["A3"].PutValue("Desk");
                cells["B3"].PutValue("Furniture");
                cells["C3"].PutValue(350);

                // Apply a simple style to the header (optional, just to illustrate)
                Style headerStyle = workbook.CreateStyle();
                headerStyle.Font.IsBold = true;
                headerStyle.ForegroundColor = System.Drawing.Color.LightGray;
                headerStyle.Pattern = BackgroundType.Solid;
                StyleFlag flag = new StyleFlag { Font = true, CellShading = true };
                cells.CreateRange("A1:C1").ApplyStyle(headerStyle, flag);

                // 2. Save the workbook as HTML
                string htmlFilePath = Path.Combine(Environment.CurrentDirectory, "report.html");
                HtmlSaveOptions htmlOptions = new HtmlSaveOptions
                {
                    ExportActiveWorksheetOnly = true,
                    ExportGridLines = true,
                    // Keep the HTML in a single file (no external resources) for simplicity
                    ExportImagesAsBase64 = true
                };
                workbook.Save(htmlFilePath, htmlOptions);
                Console.WriteLine($"Workbook saved as HTML to: {htmlFilePath}");

                // 3. Load the generated HTML
                string htmlContent = File.ReadAllText(htmlFilePath, Encoding.UTF8);

                // 4. Insert custom CSS for the header row class
                const string customCss = @"
    <style type=""text/css"">
        .header-row {
            background-color:#DDEEFF;
            font-weight:bold;
        }
    </style>
";
                // Insert the CSS just before the closing </head> tag
                htmlContent = Regex.Replace(htmlContent, @"</head>", customCss + "\n</head>", RegexOptions.IgnoreCase);

                // 5. Add the custom CSS class to the first data row (<tr>) that represents the header
                // Find the first <tr> after <tbody> (or after <table>) and add class="header-row"
                // This regex captures the opening <tr> tag without attributes
                string pattern = @"(<tr\s*)(>)";
                // Replace only the first occurrence
                htmlContent = Regex.Replace(htmlContent, pattern, "$1class=\"header-row\"$2", RegexOptions.IgnoreCase, TimeSpan.FromSeconds(5));

                // 6. Write the modified HTML back to the file
                File.WriteAllText(htmlFilePath, htmlContent, Encoding.UTF8);
                Console.WriteLine("Custom CSS class added to header rows successfully.");
            }
            catch (Exception ex)
            {
                Console.WriteLine("An error occurred:");
                Console.WriteLine(ex.Message);
                Console.WriteLine(ex.StackTrace);
            }
        }
    }
}
